# application.yml
p169:
  acci:
    record-type: "ACI"
    branch: 485
    clave-saldo-actual: 2
    clave-saldo-disponible: 354
    moneda-dolares: 5

// ---------------------------------------------------------------------------
@Component
@RequiredArgsConstructor
public class MapeoAcci {

    private final P169Properties.Acci cfg;

    /** 200-MUEVE-INFORMACION-SDOS y 250-MUEVE-CVESDO-IMP. */
    public AcciRecord.Builder desde(SaldoContrato s) {
        boolean usd = s.moneda() == cfg.monedaDolares();
        char estatus = switch (s.status()) {
            case 0  -> ' ';
            case 1  -> 'B';
            default -> 'C';
        };
        BigDecimal actual = s.importe(cfg.claveSaldoActual()).orElse(BigDecimal.ZERO.setScale(2));
        BigDecimal dispon = s.importe(cfg.claveSaldoDisponible()).orElse(BigDecimal.ZERO.setScale(2));

        return AcciRecord.builder()
                .recordType(cfg.recordType()).branch(cfg.branch())
                .ccyCode(usd ? 126 : 0).swiftCcy(usd ? "USD" : "MXN")
                .statInd(estatus).catCode(1)
                .bankNonBank("001").mail("1111").mailToCollect('0').mailRuleOff("00")
                .acctBal(SignedAmount.of(actual)).lcyAcctBal(SignedAmount.of(actual))
                .dispValBal(SignedAmount.of(dispon))
                .lastTxnDate(Fechas.siete(s.fecUltMov()))   // MOVE 9(08) a 9(07): pierde el primer dígito
                .contrato(s.contrato());
    }
}

@Component
@StepScope
@RequiredArgsConstructor
public class CompletaSaldoS408Processor implements ItemProcessor<AcciRecord, AcciRecord> {

    private final SaldosS408Client s408;             // SALDOSXCTO IN CONL022S408, función 02
    private final RetryTemplate esperaS408;          // 96 = ocupado: WAIT(300) y reintento
    @Value("#{jobParameters['fechaProceso']}") private LocalDate fechaProceso;

    @Override
    public AcciRecord process(AcciRecord r) {
        S408Respuesta resp = esperaS408.execute(ctx -> {
            S408Respuesta x = s408.saldosPorContrato(r.contrato(), fechaProceso);
            if (x.resultado() == 96) throw new S408OcupadoException();
            return x;
        });
        if (resp.resultado() != 0) {
            log.error("ERROR AL CONSULTAR S408 CON CTO. : {} RESULT : {}", r.contrato(), resp.resultado());
            return r;                                // se envía con los saldos del batch
        }
        // Aritmética con signo; el fuente opera sobre magnitudes sin signo (ver riesgo).
        BigDecimal disponible = r.dispValBal().valor().add(resp.disponible());
        AcciRecord.Builder b = r.toBuilder().dispValBal(SignedAmount.of(disponible));
        if (resp.saldo().signum() > 0) {
            BigDecimal actual = r.acctBal().valor().subtract(resp.saldo());
            b.acctBal(SignedAmount.of(actual)).lcyAcctBal(SignedAmount.of(actual))
             .lastTxnDate(Fechas.siete(fechaProceso));
        }
        return b.build();
    }
}

@Bean
RetryTemplate esperaS408() {
    return RetryTemplate.builder()
            .retryOn(S408OcupadoException.class)
            .fixedBackoff(Duration.ofSeconds(300))   // WAIT(300)
            .infiniteRetry()                         // PERFORM ... UNTIL W88-S408-OK
            .build();
}

    /**
     * 310-LLAMA-S408: idéntica a 300 salvo por el manejo de errores.
     *  - 96: espera 300 s una sola vez y NO reintenta; el contrato sale con saldos del batch.
     *  - 99: se ignora sin bitácora.
     * Se mantiene el comportamiento actual detrás de una propiedad.
     */
    private S408Respuesta consultaSiguiente(AcciRecord r) {
        S408Respuesta x = s408.saldosPorContrato(r.contrato(), fechaProceso);
        if (x.resultado() == 96) {
            if (props.reintentarTodos()) {               // p169.s408.reintentar-todos: false
                return esperaS408.execute(ctx -> reconsulta(r));
            }
            esperaFija(Duration.ofSeconds(300));         // WAIT(300) sin nueva consulta
        } else if (x.resultado() != 0 && x.resultado() != 99) {
            log.error("ERROR AL CONSULTAR S408 CON CTO. : {} RESULT : {}", r.contrato(), x.resultado());
        }
        return x;
    }

// 320-LEE-CITD-T: escribe el registro ya completado y el renglón del monitor;
// en Spring Batch el ItemWriter compuesto hace ambas escrituras.
@Bean
CompositeItemWriter<AcciRecord> salidaCitd(FlatFileItemWriter<AcciRecord> sdosCitd,
                                           FlatFileItemWriter<AcciRecord> monitorCitd) {
    return new CompositeItemWriterBuilder<AcciRecord>()
            .delegates(sdosCitd, monitorCitd).build();
}

# application.yml
p169:
  envio:
    csi-emisor: 4                                   # WKS-NUMCSI = 04 (el CSI 32 se trata como 04)
    citd-destino: "S151/FILE/E01/S500ACCCD/04/10/{yyMMdd}"   # según el comentario de la línea 7704

// ---------------------------------------------------------------------------
@Configuration
public class EnvioCorresponsalFlow {

    /** 41230-ENVIA-ACCCD: CALL SYSTEM WFL USING WKS-COPY-L030 por cada archivo generado. */
    @Bean
    IntegrationFlow envioSaldosCorresponsales(P169Properties props, CsiActual csi,
                                              MessageHandler transferenciaCorresponsal) {
        return IntegrationFlow.from("saldosCorresponsalesGenerados")      // File de CITD y de BNE
                .filter(m -> csi.numero() == props.envio().csiEmisor())   // otros CSI: no envían
                .handle(transferenciaCorresponsal)                        // SFTP / MFT corporativo
                .get();
    }
}
